// Count a vote and choose one player to remove only when there is a clear winning choice.
// ballot-resolution: original MIT-licensed native educational port.
// Generated by tools/ports/generate.py; edit the specification to preserve parity.
// Input:
// [candidate_count,voter_count,...candidate_ids,...eligible_voter_ids,...[voter_id,target_id]]
// Output: [eliminated_id_or_minus_one]
// Unique nonnegative IDs; -1 is an explicit skip. Reject ineligible voters/targets and duplicate
// ballots. A plurality tie or skip win causes no elimination.
// Precondition: finite, correctly shaped data; integer indices/counts/IDs.
// See ../PORTS.md for examples, limits, and the shared test fixtures.

#include "mechanic.h"
#include <assert.h>
#include <math.h>
// Count how many numbers are in this list.
static inline double port_length(const PortVector *a) { return (double)a->count; }
// Check that a position is a whole number inside the list before using it.
static inline size_t port_index(const PortVector *a, double i) { assert(isfinite(i) && i>=0 && i<(double)a->count && floor(i)==i); return (size_t)i; }
// Read one number at a zero-based position; stop if that position does not exist.
static inline double port_get(const PortVector *a, double i) { return a->values[port_index(a,i)]; }
// Replace a number at an existing position in the list.
static inline void port_put(PortVector *a, double i, double v) { a->values[port_index(a,i)] = v; }
// Add one number to the end of the list.
static inline void port_push(PortVector *a, double v) { assert(a->count<PORT_CAPACITY); a->values[a->count++]=v; }

// 1. Accept at most one vote from each eligible voter.
// 2. Count votes for eligible candidates; minus one means skip.
// 3. Find the largest vote count.
// 4. A tie, no votes, or a winning skip vote removes nobody.
PortVector game_ballot_resolution_compute(PortVector data) {
    double n = 0;
    double voters = 0;
    PortVector counts = {0};
    double i = 0;
    PortVector seen = {0};
    double best = 0;
    double winner = 0;
    double tied = 0;
    double voter = 0;
    double target = 0;
    double eligible = 0;
    double j = 0;
    double index = 0;
    double count = 0;
    n = port_get(&data, 0.0);
    voters = port_get(&data, 1.0);
    if (((n < 0.0) || (voters < 0.0))) {
        return (PortVector){.values={-(2.0)}, .count=1};
    }
    counts = (PortVector){.values={0}, .count=0};
    i = 0.0;
    while ((i < (n + 1.0))) {
        port_push(&counts, 0.0);
        i += 1.0;
    }
    seen = (PortVector){.values={0}, .count=0};
    i = ((2.0 + n) + voters);
    while ((i < port_length(&data))) {
        voter = port_get(&data, i);
        target = port_get(&data, (i + 1.0));
        eligible = 0.0;
        j = 0.0;
        while ((j < voters)) {
            if ((port_get(&data, ((2.0 + n) + j)) == voter)) {
                eligible = 1.0;
            }
            j += 1.0;
        }
        j = 0.0;
        while ((j < port_length(&seen))) {
            if ((port_get(&seen, j) == voter)) {
                eligible = 0.0;
            }
            j += 1.0;
        }
        if ((eligible == 0.0)) {
            return (PortVector){.values={-(2.0)}, .count=1};
        }
        port_push(&seen, voter);
        index = -(1.0);
        if ((target == -(1.0))) {
            index = n;
        }
        j = 0.0;
        while ((j < n)) {
            if ((port_get(&data, (2.0 + j)) == target)) {
                index = j;
            }
            j += 1.0;
        }
        if ((index < 0.0)) {
            return (PortVector){.values={-(2.0)}, .count=1};
        }
        port_put(&counts, index, (port_get(&counts, index) + 1.0));
        i += 2.0;
    }
    best = 0.0;
    winner = -(1.0);
    tied = 0.0;
    i = 0.0;
    while ((i < (n + 1.0))) {
        count = port_get(&counts, i);
        if ((count > best)) {
            best = count;
            winner = i;
            tied = 0.0;
        } else {
            if ((count == best)) {
                tied = 1.0;
            }
        }
        i += 1.0;
    }
    if (((best == 0.0) || (tied == 1.0) || (winner == n))) {
        return (PortVector){.values={-(1.0)}, .count=1};
    }
    return (PortVector){.values={port_get(&data, (2.0 + winner))}, .count=1};
}
